# rgb_to_hex :: (255, 255, 255)
def rgb_to_hex(r, g, b):
    return '#{:02x}{:02x}{:02x}'.format(int(r) & 0xff, int(g) & 0xff, int(b) & 0xff)

if __name__ == '__main__':
    print(rgb_to_hex((255, 255, 255)))

